using System; using System.Drawing; using System.Drawing.Drawing2D; using System.Windows.Forms;
sealed class PhantomTheme:ToolStripProfessionalRenderer {
static readonly Color Blue=Color.FromArgb(0,107,238),Ink=Color.FromArgb(15,15,19); static readonly Font Body=new Font("Microsoft YaHei UI",10.5f,FontStyle.Bold),Large=new Font("Arial",25,FontStyle.Bold|FontStyle.Italic),Small=new Font("Arial",8,FontStyle.Bold);
public PhantomTheme(){RoundedEdges=false;}
public static void Apply(ContextMenuStrip menu){menu.Renderer=new PhantomTheme();Style(menu);menu.Items[0].Tag="header";menu.Items[0].Size=new Size(300,87);menu.Items[0].Margin=new Padding(0,0,0,7);var foot=new ToolStripMenuItem("DESKTOP COMPANION  /  01"){Enabled=false,Tag="footer",AutoSize=false,Size=new Size(300,28)};menu.Items.Add(foot);}
static void Style(ToolStripDropDown m){m.BackColor=Ink;m.ForeColor=Color.White;m.Font=Body;m.Padding=new Padding(7);m.MinimumSize=new Size(314,0);m.DropShadowEnabled=true;var d=m as ToolStripDropDownMenu;if(d!=null){d.ShowImageMargin=false;d.ShowCheckMargin=false;}foreach(ToolStripItem item in m.Items){item.AutoSize=false;item.Size=new Size(300,item is ToolStripSeparator?13:38);item.Margin=new Padding(0,1,0,1);var mi=item as ToolStripMenuItem;if(mi!=null&&mi.HasDropDownItems)Style(mi.DropDown);}}
protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e){var g=e.Graphics;g.Clear(Ink);int w=e.ToolStrip.Width,h=e.ToolStrip.Height;using(var p=new Pen(Color.White,2))g.DrawPolygon(p,new[]{new Point(1,1),new Point(w-2,1),new Point(w-2,h-17),new Point(w-18,h-2),new Point(1,h-2)});using(var b=new SolidBrush(Blue))g.FillPolygon(b,new[]{new Point(w-36,h-5),new Point(w-7,h-34),new Point(w-7,h-6)});}
protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e){}
protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e){var g=e.Graphics;int w=Math.Min(e.Item.Width,e.Item.Owner.ClientSize.Width-14),h=e.Item.Height;g.SmoothingMode=SmoothingMode.AntiAlias;string tag=e.Item.Tag as string;if(tag=="header"){using(var b=new SolidBrush(Blue))g.FillPolygon(b,new[]{new Point(0,0),new Point(w,0),new Point(w-12,h-8),new Point(0,h)});g.DrawString("AMIYA",Large,Brushes.White,new PointF(12,5));g.DrawString("阿米娅  /  桌宠控制",Body,Brushes.White,new PointF(16,51));using(var p=new Pen(Color.White,2))g.DrawLine(p,w-63,14,w-22,14);return;}if(tag=="footer")return;var mi=e.Item as ToolStripMenuItem;if(mi!=null && mi.Checked){using(var pen=new Pen(Color.White,2))g.DrawLines(pen,new[]{new Point(13,19),new Point(18,24),new Point(26,13)});}if(e.Item.Selected&&e.Item.Enabled){using(var b=new SolidBrush(Color.White))g.FillPolygon(b,new[]{new Point(5,4),new Point(w-2,0),new Point(w-12,h-2),new Point(0,h-3)});using(var b=new SolidBrush(Blue))g.FillPolygon(b,new[]{new Point(9,5),new Point(w-6,3),new Point(w-15,h-5),new Point(4,h-6)});}}
protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e){string tag=e.Item.Tag as string;if(tag=="header")return;if(tag=="footer"){TextRenderer.DrawText(e.Graphics,e.Text,Small,new Rectangle(14,3,e.Item.Width-25,e.Item.Height),Color.FromArgb(150,150,155),TextFormatFlags.Left|TextFormatFlags.VerticalCenter);return;}var rect=new Rectangle(37,0,e.Item.Width-58,e.Item.Height);TextRenderer.DrawText(e.Graphics,e.Text,Body,rect,e.Item.Enabled?Color.White:Color.Gray,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix);}
protected override void OnRenderItemCheck(ToolStripItemImageRenderEventArgs e){using(var p=new Pen(Color.White,2)){e.Graphics.DrawLines(p,new[]{new Point(13,19),new Point(18,24),new Point(26,13)});}}
protected override void OnRenderArrow(ToolStripArrowRenderEventArgs e){int x=Math.Min(e.Item.Width,e.Item.Owner.ClientSize.Width-14)-21,y=e.Item.Height/2;using(var b=new SolidBrush(Color.White))e.Graphics.FillPolygon(b,new[]{new Point(x-3,y-5),new Point(x+3,y),new Point(x-3,y+5)});}
protected override void OnRenderSeparator(ToolStripSeparatorRenderEventArgs e){using(var p=new Pen(Color.FromArgb(90,90,95)))e.Graphics.DrawLine(p,13,6,e.Item.Width-14,6);}
protected override void OnRenderImageMargin(ToolStripRenderEventArgs e){}
}



